using Aict.Core;
using Aict.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass]public sealed class ActivityTests {
    [TestMethod]public void NonQuotaActivitySplitsMidnightAndSeparatesApplicationFromWebsite(){var start=new DateTimeOffset(2026,11,3,15,59,59,TimeSpan.Zero);var rows=ActivityAccounting.Expand(new("Asia/Shanghai",new(start,TimeSpan.FromSeconds(2),new("app-id","example.com")),"Browser.exe"));Assert.AreEqual(4,rows.Length);Assert.AreEqual(2,rows.Count(r=>r.Kind=="app"));Assert.IsTrue(rows.All(r=>r.KnownTicks==TimeSpan.TicksPerSecond));}
    [TestMethod]public void IdleLockedSleepAndMissingObservationsHaveDistinctMeaning(){var start=new DateTimeOffset(2026,11,3,6,0,0,TimeSpan.Zero);var slice=new UsageSlice(start,TimeSpan.FromSeconds(5),new("app"));Assert.AreEqual(0,ActivityAccounting.Expand(new("UTC",slice with{SessionLocked=true},"App.exe")).Length);Assert.AreEqual(0,ActivityAccounting.Expand(new("UTC",slice with{IdleAtStart=TimeSpan.FromSeconds(60)},"App.exe")).Length);var gap=ActivityAccounting.Expand(new("UTC",slice with{ObservationKnown=false},"App.exe")).Single();Assert.AreEqual(0L,gap.KnownTicks);Assert.AreEqual(TimeSpan.FromSeconds(5).Ticks,gap.UnknownTicks);}
    [TestMethod]public void IncrementalActivityStorageDoesNotChangeRulesAndEscapesSpreadsheetFormulas(){string dir=Path.Combine(Environment.GetEnvironmentVariable("AICT_TEST_ROOT")!,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var now=new DateTimeOffset(2026,11,3,6,0,0,TimeSpan.Zero);var snapshot=new EngineSnapshot{Clock=new(now,true)};string file=Path.Combine(dir,"engine.sqlite");var state=StateRepository.CreateNew(file,snapshot);var activity=new ActivityRepository(file);var frame=new ActivityFrame("UTC",new(now,TimeSpan.FromSeconds(2),new("application")),"=UNTRUSTED.exe");activity.Add([frame]);activity.Add([frame]);Assert.AreEqual(TimeSpan.FromSeconds(4).Ticks,activity.Read().Single().KnownTicks);Assert.AreEqual(0L,state.Read().Revision);StringAssert.Contains(ActivityRepository.ToCsv(activity.Read()),"'=UNTRUSTED.exe");}
}
